      "vietnameseTranslation": "Jared Chan [8:52 Sáng]\nXin chào, tôi theo lịch sẽ giao một bộ bàn ăn mới đến nhà bạn vào sáng mai. Bạn có nhà lúc 10 giờ không?\nBonnie Townsend [8:55 Sáng]\nChào anh! Tôi sẽ đi làm cả ngày. Nhưng tôi đã để lại một thẻ khóa tại quầy an ninh của tòa nhà. Anh có thể lấy nó và sử dụng thang máy dịch vụ.\nJared Chan [8:56 Sáng]\nTôi hiểu rồi. Và tôi nên để các món đồ ở đâu trong căn hộ của bạn?\nBonnie Townsend [8:57 Sáng]\nTôi có một phòng ăn đi qua cửa đầu tiên bên trái. Căn phòng trống và anh có thể để đồ ở bất cứ đâu trong đó.\nJared Chan [8:59 Sáng]\nTôi sẽ làm như vậy. Bạn có muốn tôi dọn dẹp bao bì đóng gói luôn không?\nBonnie Townsend [9:01 Sáng]\nTôi rất cảm kích điều đó. Anh có biết liệu có cần lắp ráp gì không?\nJared Chan [9:02 Sáng]\nKhông. Mọi thứ đã được lắp ráp hoàn chỉnh rồi.",
