    "vietnameseMeaning": "Một lý do ông Anderson liên hệ với cô Tatou là gì? - Để yêu cầu các hình ảnh phù hợp cho trang web.",
    "stage": 4,
    "badge": "💎 Giai đoạn 4: Hacker 3 Test 1",
