      "title": "Blake Anderson Email to Noelle Tatou",
      "type": "Email",
      "content": "TO: Noelle Tatou <notat@tatoudecor.com>\nFROM: Blake Anderson <blander@bawebdesign.com>\nSUBJECT: Your Web site\nDATE: October 9\nHi, Noelle.\nI have just completed a basic layout for your new Web site. Everything looks good and follows your specifications. I'll need a few more days to have it up and running and will make sure you get to look through everything before the site is activated. But I have encountered one issue that I need your help with. I uploaded the files you e-mailed to me about your products. However, the images you sent are low-resolution, so they aren't very clear. Do you happen to have better quality images? If so, please send them to me so that I can use them on the site. If you don't have any higher resolution images, I'd suggest taking additional photos. Customers will want to clearly see what your merchandise looks like.\nLet me know if you have any questions.\nBlake",
      "vietnameseTranslation": "ĐẾN: Noelle Tatou <notat@tatoudecor.com>\nTỪ: Blake Anderson <blander@bawebdesign.com>\nCHỦ ĐỀ: Trang web của bạn\nNGÀY: 9 tháng 10\nChào Noelle,\nTôi vừa hoàn thành bố cục cơ bản cho trang web mới của bạn. Mọi thứ trông rất ổn và tuân theo đúng yêu cầu của bạn. Tôi sẽ cần thêm vài ngày nữa để đưa trang web vào hoạt động và sẽ đảm bảo bạn được xem qua mọi thứ trước khi trang web được kích hoạt. Tuy nhiên, tôi gặp phải một vấn đề cần sự trợ giúp của bạn. Tôi đã tải lên các tệp bạn gửi qua email về các sản phẩm của bạn. Nhưng những hình ảnh bạn gửi có độ phân giải thấp nên không được rõ ràng lắm. Bạn có hình ảnh chất lượng tốt hơn không? Nếu có, vui lòng gửi chúng cho tôi để tôi đưa lên trang web. Nếu không có ảnh độ phân giải cao hơn, tôi khuyên bạn nên chụp thêm ảnh. Khách hàng sẽ muốn thấy rõ hàng hóa của bạn trông như thế nào.\nHãy cho tôi biết nếu bạn có bất kỳ câu hỏi nào nhé.\nBlake",
