    "explanation": "Bài viết nói về việc chuỗi đồ ăn nhanh Lucy's điều chỉnh thực đơn, sử dụng nguyên liệu hữu cơ, giảm đường muối, tăng đồ uống lành mạnh -> Những thay đổi về sản phẩm của một công ty dịch vụ ăn uống ('Product changes of a food service company').",
