      "title": "Dimensional Printers Warranty Webpage",
      "type": "Webpage",
      "content": "http://www.dimensionalprinters.com/guarantee\nHOME | PRODUCTS | SHOP | GUARANTEE | COMPANY | REPAIR CENTERS | CONTACT\nDimensional Printers' Guarantee to You\nDimensional Printers is proud to offer guarantees on all our products. This includes all 3D printers, software, and replacement cartridges.\nAll 3D printers come with a two-year warranty. That means if your device breaks down or becomes inoperable, it will be repaired or replaced for free within the warranty period. Simply return the device to one of our authorized repair centers. You can find the one nearest you by clicking on REPAIR CENTERS. Warranties can be extended for an additional charge, starting at $32 per year. Please note that warranties may not be honored if the owner fails to perform regular printer upkeep. Instructions for this can be found in the user manual.\nIf a cartridge is defective, you may simply return it to the retail outlet where it was purchased for an exchange. If you purchased it on our Web site, return the item to us in the mail. We will reimburse you for shipping fees and send you a replacement.\nShould you have any difficulties using or installing any of our products, feel free to click on CONTACT. You'll have the option of sending an e-mail or text to one of our service representatives.\nThank you for your business, and please let us know how we can be of further assistance.",
      "vietnameseTranslation": "http://www.dimensionalprinters.com/guarantee\nTRANG CHỦ | SẢN PHẨM | CỬA HÀNG | BẢO HÀNH | CÔNG TY | TRUNG TÂM SỬA CHỮA | LIÊN HỆ\nCam Kết Bảo Hành Của Dimensional Printers Dành Cho Bạn\nDimensional Printers tự hào cung cấp chế độ bảo hành cho tất cả các sản phẩm của chúng tôi. Điều này bao gồm tất cả các máy in 3D, phần mềm và hộp mực thay thế.\nTất cả các máy in 3D đều được bảo hành hai năm. Điều đó có nghĩa là nếu thiết bị của bạn bị hỏng hóc hoặc không thể hoạt động, nó sẽ được sửa chữa hoặc thay thế miễn phí trong thời gian bảo hành. Chỉ cần gửi trả thiết bị về một trong những trung tâm sửa chữa được ủy quyền của chúng tôi. Bạn có thể tìm thấy trung tâm gần nhất bằng cách nhấp vào TRUNG TÂM SỬA CHỮA. Thời hạn bảo hành có thể được gia hạn thêm với một khoản phí phụ trội, bắt đầu từ 32 đô la mỗi năm. Xin lưu ý rằng yêu cầu bảo hành có thể không được chấp nhận nếu chủ sở hữu không thực hiện bảo dưỡng máy in định kỳ. Hướng dẫn cho việc này có thể tìm thấy trong sách hướng dẫn sử dụng.\nNếu hộp mực bị lỗi, bạn chỉ cần mang trả lại cho đại lý bán lẻ nơi đã mua để đổi hàng. Nếu bạn mua trên trang web của chúng tôi, hãy gửi trả sản phẩm qua đường bưu điện. Chúng tôi sẽ hoàn lại phí vận chuyển và gửi sản phẩm thay thế cho bạn.\nNếu bạn gặp bất kỳ khó khăn nào trong việc sử dụng hoặc cài đặt bất kỳ sản phẩm nào của chúng tôi, vui lòng nhấp vào LIÊN HỆ. Bạn sẽ có tùy chọn gửi email hoặc tin nhắn văn bản tới một trong các đại diện dịch vụ của chúng tôi.\nCảm ơn bạn đã tin tưởng ủng hộ và vui lòng cho chúng tôi biết nếu chúng tôi có thể hỗ trợ thêm điều gì.",
