      "content": "Fred Cameron [10:34 A.M.]\nSo, I want to make some initial plans for the company booth at the trade fair in Austin on November 1 and 2. We need at least three people at the booth on both days. Are any of you available?\nAmber Krane [10:36 A.M.]\nWhat time is the fair? I am supposed to attend a function at my daughter's school at 2 p.m. on November 2.\nRajiv Gopal [10:37 A.M.]\nI will be at a conference on November 1. But I can help out on the other date.\nDonna Jackson [10:37 A.M.]\nMark me down for both days.\nFred Cameron [10:38 A.M.]\nAmber, it's from 10 A.M. until 7 P.M. So, could you do November 1? And thanks, Donna.\nAmber Krane [10:39 A.M.]\nYes, I can do the first day.\nDonna Jackson [10:40 A.M.]\nDo we need to be at the venue early for setup?\nFred Cameron [10:42 A.M.]\nThat would help me out a lot. If you could all arrive at around 9 A.M. on the first date, I'd appreciate it.\nRajiv Gopal [10:43 A.M.]\nAnd I can help you take everything down at the end of the fair.\nFred Cameron [10:45 A.M.]\nPerfect! Okay, I'm going to make a schedule this morning. I'll send a copy to all of you by e-mail this afternoon. Thanks!",
