          "clueLocation": "Bài 2 tiêu đề & Bài 1 bảng Packages",
          "clueQuote": "House $325,990 -> Package 3 ($250,000 to $499,999): Monthly Rate $49.",
          "scanningTip": "Lấy giá bán $325,990 tra vào khung giá Package 3."
