      "title": "Sands Museum Membership Brochure & Letter",
      "type": "Double Passage",
      "content": "Sands Museum Membership\nSupport one of the country's largest museums and enjoy access to multiple benefits throughout the year. With a vast collection of biological specimens, the Sands Museum plays a vital role in scientific research and education. Join today!\nCategories:\n- INDIVIDUAL: $85 (1 year), $160 (2 years)\n- STUDENT: $65 (1 year), $120 (2 years)\n- FAMILY: $240 (1 year), $460 (2 years)\n- SENIOR: $55 (1 year), $100 (2 years)\nIncluded are the following:\n• Unlimited general admission to the Sands Museum\n• Free or discounted tickets to temporary exhibitions based on your member category\n• Free admission to over 200 affiliated science museums around the country\n• Free subscription to Pathfinder, our quarterly member magazine\n• Invitations to members-only viewings of special exhibitions\n• 10% discount in the museum restaurant Sands of Time\n• 10% discount in the museum gift shop\n• 10% discount on space leasing for private events held at the museum\nFor more information, call 555-3095 or visit www.sandsmuseum.org. The Sands Museum is located in Cincinnati, Ohio.\n---\nThe Sands Museum\nCincinnati, Ohio | July 24\nMs. Connie Pastore\n3418 29th St., Muncie, IN 47302\nDear Ms. Pastore,\nWelcome to the Sands Museum!\nYou have been given the gift of a membership by Bernice Hawkins. As a member, you and up to three additional members of your household are entitled to a range of benefits for 12 months. These include unlimited basic admission, invitations to special events, and so much more. A calendar with information on upcoming exhibitions at the museum has been included with this letter for your reference.\nPlease also find your official Sands Museum card and unique activation number enclosed. To begin your membership, visit our Web site at www.sandsmuseum.org/membership, and enter the code beneath the prompt \"Activate Now.\" Within two weeks of activation, your first issue of our member magazine will be sent to you in the mail.\nPlease note that all membership beneficiaries must be listed by name under your account. You may also be asked to supply a driver's license or passport photos to prove your familial relations.\nSincerely,\nEric Swale, Member Coordinator",
