      "title": "Beeker Corporation Internship Program Notice, Memo, and Application",
      "type": "Triple Passage",
      "content": "Beeker Corporation Internship Program Now Open\nThe Beeker Corporation Internship Program is now accepting applications. The internship period runs for eight weeks from June to August. Applications will be accepted until March 29 of next year. All interviews will take place online.\nThe Internship Program grants local students the opportunity to take a paid position at the company's Chicago headquarters. It provides valuable experience within a global company specializing in the research, production, and marketing of drugs and medicines.\nA recruitment committee representing different areas of the company will oversee the selection process, making an effort to match students to areas of interest. However, placements are subject to availability. Work hours are full-time from Monday to Thursday, while Fridays are reserved for mandatory professional development seminars.\nFor more information, visit www.beekercorp.com.\n---\nBeeker Corporation MEMO\nTo: All department heads | From: Janet Chong | Subject: Update on internship program | Date: April 15\nI want to let you know that we've begun screening applicants and have already eliminated those who failed to submit an adequate internship essay along with their application. So far, we've narrowed the field to 150. This will go down further as we evaluate for skill and potential fit.\nIt must be noted that some departments—sales, information technology, and research and development—have received a larger share of applicants. For these departments, we will be prioritizing students preparing to graduate. Applicants who may be excluded by this criterion but otherwise show promise will be considered for open positions in other departments of preference.\nFinal selections will be based on interviews in the coming two weeks, and applicable department heads should accompany me in the process so that relevant and technical questions can be asked. I'll send you the schedule next week so you know which ones to participate in. We expect to have all 60 candidates placed by the start of May. For questions or concerns, please call extension 48.\n---\nBeeker Corporation Internship Program APPLICATION FORM\nPersonal Details - Date: March 16 | Name: Sylvia Cruz | Telephone: 555-5209\nAddress: Room 28, Hanson Dormitory, Belmont University, 2231 Central Avenue, Chicago, IL 60639\nEmail: s.cruz@belmont.edu\nAcademic status - School: Belmont University | Level: [ ] Sophomore [ ] Junior [X] Senior | Major: Chemical biology | GPA: 3.7\nList your top four choices for placement:\n1. Research and development\n2. Engineering and manufacturing\n3. Information technology\n4. Corporate communications\nPlease attach copies of the following to your application: cover letter, reference letters, latest school transcripts, internship essay, and student ID.",
      "vietnameseTranslation": "Chương Trình Thực Tập Của Tập Đoàn Beeker Hiện Đang Mở Đơn\nChương trình thực tập của Tập đoàn Beeker hiện đang tiếp nhận hồ sơ. Thời gian thực tập kéo dài 8 tuần từ tháng 6 đến tháng 8. Đơn đăng ký sẽ được tiếp nhận đến ngày 29 tháng 3 năm sau. Tất cả các cuộc phỏng vấn sẽ diễn ra trực tuyến.\nChương trình thực tập mang đến cho sinh viên địa phương cơ hội đảm nhận một vị trí được trả lương tại trụ sở chính của công ty ở Chicago. Chương trình mang lại trải nghiệm quý giá trong một công ty toàn cầu chuyên về nghiên cứu, sản xuất và tiếp thị dược phẩm và thuốc men.\nMột hội đồng tuyển dụng đại diện cho các phòng ban khác nhau của công ty sẽ giám sát quá trình tuyển chọn, nỗ lực sắp xếp sinh viên vào các lĩnh vực quan tâm. Tuy nhiên, các vị trí sắp xếp tùy thuộc vào số lượng còn trống. Thời gian làm việc toàn thời gian từ thứ Hai đến thứ Năm, trong khi thứ Sáu dành riêng cho các buổi hội thảo phát triển chuyên môn bắt buộc.\n---\nBản ghi nhớ của Tập đoàn Beeker\nĐến: Tất cả trưởng phòng | Từ: Janet Chong | Ngày: 15 tháng 4\nTôi muốn thông báo rằng chúng ta đã bắt đầu sàng lọc các ứng viên và đã loại bỏ những người không nộp bài luận thực tập đầy đủ cùng với đơn đăng ký. Cho đến nay, chúng ta đã thu hẹp danh sách xuống còn 150 người. Con số này sẽ giảm thêm khi chúng ta đánh giá về kỹ năng và mức độ phù hợp tiềm năng.\nCần lưu ý rằng một số bộ phận—kinh doanh, công nghệ thông tin và nghiên cứu & phát triển (R&D)—đã nhận được số lượng ứng viên lớn hơn. Đối với các bộ phận này, chúng ta sẽ ưu tiên những sinh viên chuẩn bị tốt nghiệp. Những ứng viên có thể bị loại theo tiêu chí này nhưng có triển vọng sẽ được xem xét cho các vị trí còn trống ở các bộ phận ưu tiên khác.\nCác lựa chọn cuối cùng sẽ dựa trên các cuộc phỏng vấn trong hai tuần tới, và các trưởng bộ phận liên quan nên tham gia cùng tôi để có thể đặt ra các câu hỏi chuyên môn và kỹ thuật. Tôi sẽ gửi cho các bạn lịch trình vào tuần tới. Chúng ta dự kiến sẽ phân bổ xong cả 60 ứng viên trước đầu tháng Năm.\n---\nĐơn Đăng Ký Chương Trình Thực Tập\nNgày: 16 tháng 3 | Họ tên: Sylvia Cruz\nTrường: Đại học Belmont | Trình độ: [X] Sinh viên năm cuối (Senior) | Chuyên ngành: Hóa sinh học | GPA: 3.7\nBốn lựa chọn hàng đầu của bạn để thực tập: 1. Nghiên cứu và phát triển (R&D); 2. Kỹ thuật và sản xuất; 3. Công nghệ thông tin; 4. Truyền thông doanh nghiệp.",
