      "title": "Navigante Airlines Offers Flyer, Email, and Booking Confirmation",
      "type": "Triple Passage",
      "content": "NAVIGANTE AIRLINES SPECIAL OFFERS\nOffers valid until dates shown.\n1. Enjoy free access to the Executive Lounge when you rent a Porte car for three days or more. Travel must occur between January 1 and December 31.\n2. Earn 1,000 Navi miles and save 25 percent on the room rate when you stay at a Comoda Hotel between January 1 and March 31.\n3. Instantly earn 150 reward points when you sign up for a Munchen Rewards Card. Points redeemable for any purchase at Munich International Airport. Valid until October 1.\n4. Earn bonus miles with Turismo when you book tours through www.navigante.com before May 15. Turismo is a leading tour provider available at over 200 destinations.\n5. Enjoy fares priced at 15% off when you use a Finma card to purchase flights between February 1 and September 30.\n6. Save on selected destinations in Australia, China, and the Middle East when you travel between January 31 and June 30.\nAll offers are subject to terms and conditions. For detailed information, consult your travel advisor, visit www.navigante.com, or download our free mobile application Navi Plus.\n---\nTo: Eloisa Perez <e.perez@saludos.com>\nFrom: Rafael Garcia <r.garcia@navigante.com>\nSubject: Navi miles | Date: August 10\nDear Ms. Perez,\nI've checked your account as requested. The miles you earned on your previous trip to Costa Rica, including the bonus ones, will soon be added to your account.\nAs for your other inquiry, you may fund your upcoming trip using a combination of miles and a credit or debit card. A round-trip, economy-class flight to Los Angeles would cost about $1,050 or 52,500 Navi miles. If you use all of your accumulated miles, you need only pay a balance of $826.78. I highly recommend that you book your trip before some of your miles expire.\nPlease let me know if I can be of any further assistance.\nSincerely, Rafael Garcia, Travel Advisor, Navigante Airlines\n---\nBOOKING CONFIRMATION\nThank you for booking your flight with Navigante Airlines. Now flying from Argentina to more locations around the world!\nPassenger Name: Eloisa Perez | Navi Member Number: B04JL6192\nBooking ID: 383920210A | Navi Miles Used: 6,623\nPayment Provider: Finma | Card Number: XXXX-XXXX-XXXX-1876\nPlease expect an e-mail from Paresda Insurance with your policy details shortly.\nDeparture: Flight NA4762 | Buenos Aires to Los Angeles | September 25, 8:00 A.M. -> September 25, 9:15 P.M. | Class: Economy | 13 hours, 15 minutes (0 stops)\nArrival: Flight NA4795 | Los Angeles to Buenos Aires | October 14, 8:00 A.M. -> October 14, 10:45 P.M. | Class: Economy | 13 hours, 15 minutes (0 stops)",
      "vietnameseTranslation": "CÁC ƯU ĐÃI ĐẶC BIỆT CỦA HÃNG HÀNG KHÔNG NAVIGANTE AIRLINES\nƯu đãi có giá trị đến ngày hiển thị.\n1. Tận hưởng quyền sử dụng Phòng chờ Thương gia miễn phí khi bạn thuê xe Porte từ ba ngày trở lên. Chuyến đi phải diễn ra từ ngày 1 tháng 1 đến ngày 31 tháng 12.\n2. Tích lũy 1.000 dặm bay Navi và tiết kiệm 25% giá phòng khi bạn lưu trú tại Khách sạn Comoda từ ngày 1 tháng 1 đến ngày 31 tháng 3.\n3. Nhận ngay 150 điểm thưởng khi đăng ký Thẻ Munchen Rewards. Điểm có thể đổi cho bất kỳ giao dịch mua nào tại Sân bay Quốc tế Munich. Có giá trị đến ngày 1 tháng 10.\n4. Nhận dặm bay thưởng với Turismo khi bạn đặt các chuyến tham quan qua www.navigante.com trước ngày 15 tháng 5. Turismo là nhà cung cấp tour hàng đầu có mặt tại hơn 200 điểm đến.\n5. Tận hưởng giá vé giảm 15% khi bạn sử dụng thẻ Finma để mua vé máy bay từ ngày 1 tháng 2 đến ngày 30 tháng 9.\n6. Tiết kiệm cho các điểm đến đã chọn ở Úc, Trung Quốc và Trung Đông khi bạn đi du lịch từ ngày 31 tháng 1 đến ngày 30 tháng 6.\n---\nKính gửi cô Perez,\nTôi đã kiểm tra tài khoản của cô theo yêu cầu. Số dặm bay cô tích lũy được trong chuyến đi Costa Rica trước đây, bao gồm cả các dặm thưởng, sẽ sớm được cộng vào tài khoản của cô.\nVề câu hỏi khác của cô, cô có thể thanh toán cho chuyến đi sắp tới bằng cách kết hợp giữa dặm bay và thẻ tín dụng hoặc thẻ ghi nợ. Một chuyến bay khứ hồi hạng phổ thông đến Los Angeles sẽ có giá khoảng 1.050 USD hoặc 52.500 dặm Navi. Nếu sử dụng tất cả số dặm đã tích lũy, cô chỉ cần thanh toán số dư là 826,78 USD. Tôi đặc biệt khuyên cô nên đặt chuyến đi trước khi một số dặm bay của cô hết hạn.\n---\nXÁC NHẬN ĐẶT CHỖ\nCảm ơn bạn đã đặt chuyến bay với Navigante Airlines. Hiện đang bay từ Argentina đến nhiều địa điểm hơn trên khắp thế giới!\nTên hành khách: Eloisa Perez\nSố dặm Navi đã sử dụng: 6.623\nĐơn vị thanh toán: Thẻ Finma\nKhởi hành: Buenos Aires đến Los Angeles | Ngày 25 tháng 9\nVề: Los Angeles đến Buenos Aires | Ngày 14 tháng 10",
